BEGIN TRANSACTION;
ASSERT (SELECT COUNT(*) FROM `up-data-intelligence-dev.up_analytics.analytics_publications` WHERE record_kind='HEAD' AND store_id=@store AND policy_hash=@policy)=1 AS 'publication_head_required';
ASSERT (SELECT generation FROM `up-data-intelligence-dev.up_analytics.analytics_publications` WHERE record_kind='HEAD' AND store_id=@store AND policy_hash=@policy)=@expected AS 'stale_publication_generation';
ASSERT NOT EXISTS(SELECT publication_id FROM `up-data-intelligence-dev.up_analytics.analytics_publications` WHERE record_kind='RECEIPT' AND store_id=@store AND policy_hash=@policy AND publication_id=@publication) AS 'receipt_already_committed';
ASSERT NOT EXISTS(SELECT as_of FROM `up-data-intelligence-dev.up_analytics.analytics_publications` WHERE record_kind='HEAD' AND store_id=@store AND policy_hash=@policy AND as_of>@as_of) AS 'analytics_model_stale';
CREATE TEMP TABLE publication_counts(model STRING, rows_generated INT64, rows_inserted INT64, rows_updated INT64, rows_deleted INT64);
ASSERT NOT EXISTS(SELECT row_key FROM _SESSION.stage_analytics_store_daily WHERE row_key IS NULL OR TRIM(row_key)='' OR store_id IS DISTINCT FROM @store OR policy_hash IS DISTINCT FROM @policy OR currency IS DISTINCT FROM @currency OR NOT (@full_0 OR CAST(order_date AS STRING) IN UNNEST(@scope_0))) AS 'invalid_staging_scope';
ASSERT NOT EXISTS(SELECT row_key FROM _SESSION.stage_analytics_store_daily GROUP BY row_key HAVING COUNT(*)>1) AS 'duplicate_staging_key';
ASSERT NOT EXISTS(SELECT order_date FROM _SESSION.stage_analytics_store_daily GROUP BY order_date HAVING COUNT(*)>1) AS 'duplicate_staging_grain';
