INSERT INTO _SESSION.publication_counts SELECT 'analytics_store_daily',(SELECT COUNT(*) FROM _SESSION.stage_analytics_store_daily),(SELECT COUNT(*) FROM _SESSION.stage_analytics_store_daily s WHERE NOT EXISTS(SELECT t.row_key FROM `up-data-intelligence-dev.up_analytics.analytics_store_daily` t WHERE t.store_id=@store AND t.policy_hash=@policy AND t.row_key=s.row_key)),(SELECT COUNT(*) FROM _SESSION.stage_analytics_store_daily s JOIN `up-data-intelligence-dev.up_analytics.analytics_store_daily` t ON t.store_id=@store AND t.policy_hash=@policy AND t.row_key=s.row_key WHERE TO_JSON_STRING(s)!=TO_JSON_STRING(t)),(SELECT COUNT(*) FROM `up-data-intelligence-dev.up_analytics.analytics_store_daily` WHERE store_id=@store AND policy_hash=@policy AND (@full_0 OR CAST(order_date AS STRING) IN UNNEST(@scope_0)) AND row_key NOT IN (SELECT row_key FROM _SESSION.stage_analytics_store_daily));
DELETE FROM `up-data-intelligence-dev.up_analytics.analytics_store_daily` WHERE store_id=@store AND policy_hash=@policy AND (@full_0 OR CAST(order_date AS STRING) IN UNNEST(@scope_0));
