UPDATE `up-data-intelligence-dev.up_analytics.analytics_publications` SET generation=@expected+1, publication_id=@publication, as_of=@as_of, finished_at=CURRENT_TIMESTAMP(), status='completed', source_watermark=@watermark WHERE record_kind='HEAD' AND store_id=@store AND policy_hash=@policy AND generation=@expected;
