INSERT INTO `up-data-intelligence-dev.up_analytics.analytics_publications` (record_kind,publication_id,store_id,policy_hash,generation,as_of,report_from,report_to,started_at,finished_at,status,analytics_version,source_watermark,models,row_counts,bytes_processed,bytes_processed_before_commit,commit_job_id) SELECT 'RECEIPT',@publication,@store,@policy,@expected+1,@as_of,@report_from,@report_to,@started_at,CURRENT_TIMESTAMP(),'completed',@version,@watermark,TO_JSON(ARRAY(SELECT model FROM _SESSION.publication_counts ORDER BY model)),TO_JSON(ARRAY(SELECT AS STRUCT model,rows_generated,rows_inserted,rows_updated,rows_deleted FROM _SESSION.publication_counts ORDER BY model)),CAST(NULL AS INT64),@bytes_before_commit,@commit_job_id;
